using System;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml.Linq;
using Microsoft.Build.Framework;

namespace Runic.Translations.Build;

/// <summary>
/// Gives a packed library's <c>Runic.Translations</c> dependency the upper bound of the version rule: code generated by
/// release N runs on runtime N or later within the same minor before 1.0 and within the same major from 1.0. So
/// <c>0.9.0</c> becomes <c>[0.9.0, 0.10.0-0)</c> and <c>1.2.0</c> becomes <c>[1.2.0, 2.0.0-0)</c>.
/// </summary>
/// <remarks>
/// <para>
/// The upper bound is the lowest prerelease of the next breaking release (<c>-0</c>), so its previews are outside the
/// range as well: NuGet sorts <c>0.10.0-preview.1</c> below <c>0.10.0</c>, and a plain <c>0.10.0</c> bound would admit it.
/// An application that uses a runtime outside the range gets NU1608 at restore.
/// </para>
/// <para>
/// NuGet takes dependency ranges from the restore output, and a package's build files join restore only from the
/// second restore on, so the range is written into the packed <c>.nuspec</c> instead, in the <c>.nupkg</c>, the
/// <c>.snupkg</c> and a written <c>.nuspec</c> file. A dependency that already names a range is left as it is; a version
/// in another format is left open with warning RTR0093.
/// </para>
/// </remarks>
public sealed class RuntimeDependencyRange : ITask
{
    private const string RuntimePackageId = "Runic.Translations";
    private static readonly Regex PlainVersion = new(
        @"^(?<major>[0-9]+)\.(?<minor>[0-9]+)\.[0-9]+(?:\.[0-9]+)?(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$", RegexOptions.CultureInvariant);

    /// <summary>The pack outputs (<c>@(NuGetPackOutput)</c>); <c>.nupkg</c>, <c>.snupkg</c> and <c>.nuspec</c> files are updated.</summary>
    [Required]
    public ITaskItem[] Packages { get; set; } = Array.Empty<ITaskItem>();

    public IBuildEngine BuildEngine { get; set; } = null!;
    public ITaskHost HostObject { get; set; } = null!;

    public bool Execute()
    {
        try
        {
            foreach (ITaskItem item in Packages)
            {
                string path = Path.GetFullPath(item.ItemSpec);
                if (!File.Exists(path)) continue;
                if (path.EndsWith(".nupkg", StringComparison.OrdinalIgnoreCase) || path.EndsWith(".snupkg", StringComparison.OrdinalIgnoreCase))
                    StampPackage(path);
                else if (path.EndsWith(".nuspec", StringComparison.OrdinalIgnoreCase))
                {
                    string? stamped = Stamp(File.ReadAllText(path, Encoding.UTF8), path);
                    if (stamped is not null) File.WriteAllText(path, stamped, new UTF8Encoding(false));
                }
            }

            return true;
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or InvalidDataException or System.Xml.XmlException)
        {
            BuildEngine.LogErrorEvent(new BuildErrorEventArgs("translations", "RTR0089", "", 0, 0, 0, 0,
                "The Runic.Translations dependency range of the package could not be written: " + exception.Message, "", nameof(RuntimeDependencyRange)));
            return false;
        }
    }

    private void StampPackage(string path)
    {
        using ZipArchive archive = ZipFile.Open(path, ZipArchiveMode.Update);
        ZipArchiveEntry? entry = archive.Entries.SingleOrDefault(static item =>
            !item.FullName.Contains('/') && item.FullName.EndsWith(".nuspec", StringComparison.OrdinalIgnoreCase));
        if (entry is null) return;
        string text;
        using (var reader = new StreamReader(entry.Open(), Encoding.UTF8)) text = reader.ReadToEnd();
        string? stamped = Stamp(text, path);
        if (stamped is null) return;
        string name = entry.FullName;
        DateTimeOffset modified = entry.LastWriteTime;
        entry.Delete();
        ZipArchiveEntry replacement = archive.CreateEntry(name, CompressionLevel.Optimal);
        replacement.LastWriteTime = modified;
        using Stream stream = replacement.Open();
        byte[] bytes = new UTF8Encoding(false).GetBytes(stamped);
        stream.Write(bytes, 0, bytes.Length);
    }

    // The .nupkg, .snupkg and .nuspec of one pack carry the same dependency; report each version once.
    private readonly System.Collections.Generic.HashSet<string> _reported = new(StringComparer.Ordinal);

    private string? Stamp(string nuspec, string path) =>
        Stamp(nuspec, version =>
        {
            if (_reported.Add(version)) BuildEngine.LogWarningEvent(new BuildWarningEventArgs("translations", "RTR0093", path, 0, 0, 0, 0,
            $"The Runic.Translations dependency version '{version}' has a format the version rule does not handle, so the package keeps it as an open " +
            "minimum version. Use a plain version such as 0.9.0, or set RunicTranslationsStampRuntimeRange to false.", "", nameof(RuntimeDependencyRange)));
        });

    /// <summary>The range for a runtime version: <c>[N, next minor-0)</c> before 1.0, <c>[N, next major-0)</c> from 1.0.</summary>
    /// <returns>The range, or <see langword="null"/> when the version has another format.</returns>
    internal static string? RangeFor(string version)
    {
        Match match = PlainVersion.Match(version);
        if (!match.Success) return null;
        if (!int.TryParse(match.Groups["major"].Value, NumberStyles.None, CultureInfo.InvariantCulture, out int major) ||
            !int.TryParse(match.Groups["minor"].Value, NumberStyles.None, CultureInfo.InvariantCulture, out int minor) ||
            major == int.MaxValue || minor == int.MaxValue)
            return null;
        string upper = major == 0
            ? "0." + (minor + 1).ToString(CultureInfo.InvariantCulture) + ".0-0"
            : (major + 1).ToString(CultureInfo.InvariantCulture) + ".0.0-0";
        return "[" + version + ", " + upper + ")";
    }

    // Returns the updated nuspec, or null when no dependency needed a range.
    internal static string? Stamp(string nuspec, Action<string>? unhandled = null)
    {
        XDocument document = XDocument.Parse(nuspec, LoadOptions.PreserveWhitespace);
        bool changed = false;
        foreach (XElement dependency in document.Descendants().Where(static element => element.Name.LocalName == "dependency"))
        {
            if (!string.Equals((string?)dependency.Attribute("id"), RuntimePackageId, StringComparison.OrdinalIgnoreCase)) continue;
            XAttribute? version = dependency.Attribute("version");
            if (version is null) continue;
            string value = version.Value.Trim();
            // A range was written on purpose, by the project or by an earlier stamp.
            if (value.StartsWith('[') || value.StartsWith('(')) continue;
            if (RangeFor(value) is not { } range)
            {
                unhandled?.Invoke(value);
                continue;
            }

            version.Value = range;
            changed = true;
        }

        if (!changed) return null;
        var builder = new StringBuilder();
        if (document.Declaration is not null) builder.Append(document.Declaration).Append('\n');
        builder.Append(document.Root!.ToString(SaveOptions.DisableFormatting));
        return builder.ToString();
    }
}
